'use strict';
let shadowSession=null;
const shadowTrack=id=>AUDIO_LESSONS.find(t=>t.id===Number(id))||AUDIO_LESSONS[0];
const audioTime=n=>Number.isFinite(n)?`${Math.floor(n/60)}:${String(Math.floor(n%60)).padStart(2,'0')}`:'0:00';
function shadowDB(){return new Promise((resolve,reject)=>{if(!window.indexedDB)return reject(Error('IndexedDB unavailable'));const req=indexedDB.open('work-english-personal-audio',1);req.onupgradeneeded=()=>req.result.createObjectStore('audio',{keyPath:'id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
async function personalAudio(id,value){const db=await shadowDB();try{return await new Promise((resolve,reject)=>{const tx=db.transaction('audio',value?'readwrite':'readonly'),store=tx.objectStore('audio');const r=value?store.put(value):store.get(id);let result;r.onsuccess=()=>{result=r.result;};tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});}finally{db.close();}}
window.cleanupListening=function(){if(shadowSession){clearTimeout(shadowSession.resume);shadowSession.audio.pause();if(shadowSession.abort)shadowSession.abort.abort();if(shadowSession.localURL)URL.revokeObjectURL(shadowSession.localURL);shadowSession=null;}document.querySelectorAll('#main audio').forEach(a=>a.pause());};
window.mountLessonAudio=function(id){const t=shadowTrack(id),timing=AUDIO_TIMINGS[t.id],host=document.querySelector('.lesson-content');if(!host||!timing)return;host.insertAdjacentHTML('afterbegin',`<section class="panel audio-lesson-preview"><span class="eyebrow">LISTEN & IMITATE / WEEK ${id}</span><h2>先听一句，再跟着说</h2><p>${esc(t.title)}</p><audio controls preload="none" src="${timing.url}"></audio><p class="source-note">原创合成示范 · Microsoft Zira（美式英语）· ${audioTime(timing.duration)}。可在跟读室逐句练习；真实听力训练继续使用官方课程。</p><div class="btn-row"><a class="btn small" href="#audio/${id}">逐句 / 循环跟读 ↗</a><a class="btn secondary small" href="${timing.url}" download="${t.slug}.wav">下载本课音频 ↓</a></div></section>`);};
window.renderListening=function(id){const t=shadowTrack(id||nextCourse().id),timing=AUDIO_TIMINGS[t.id],prefs=state.shadowPrefs?.[t.id]||{},rate=Number(prefs.rate)||1,gap=prefs.gap===undefined?3:Number(prefs.gap);$('#main').innerHTML=pageHead('LISTEN → PAUSE → IMITATE','听一句，模仿一句。','12段原创示范已经放进课程。先听重音和停顿，再逐句跟读；也可以导入自己下载的官方原音，在本机练习。')+`<div class="listening-layout"><div><section class="panel listening-player"><div class="section-head" style="margin-top:0"><span class="eyebrow">WEEK ${String(t.id).padStart(2,'0')} / ${audioTime(timing.duration)}</span><span class="chip" id="audio-source-tag">原创合成语音</span></div><h2>${esc(t.title)}</h2><p class="sub">${esc(t.focus)}</p><audio id="shadow-audio" controls preload="metadata" src="${timing.url}"></audio><div class="audio-settings"><div><label class="field" for="shadow-rate">播放速度</label><select id="shadow-rate">${[.65,.75,.9,1,1.1,1.25,1.5].map(v=>`<option value="${v}" ${v===rate?'selected':''}>${v}×</option>`).join('')}</select></div><div><label class="field" for="shadow-gap">每段后留出跟读时间</label><select id="shadow-gap">${[0,2,3,5].map(v=>`<option value="${v}" ${v===gap?'selected':''}>${v===0?'不留空隙':v+'秒'}</option>`).join('')}</select></div><label class="check-line"><input type="checkbox" class="task-check" id="shadow-loop">循环所选句 / A—B</label></div><div class="btn-row"><button class="btn small" data-shadow="whole">▷ 整段播放</button><button class="btn secondary small" data-shadow="rewind">↶ 后退5秒</button><button class="btn secondary small" data-shadow="pause">暂停跟读</button><a id="shadow-download" class="btn light small" href="${timing.url}" download="${t.slug}.wav">下载音频 ↓</a></div><p class="audio-status" id="shadow-status" role="status" aria-live="polite">点击句子编号，可播放该句；勾选循环后会在留白结束时重复。</p><div class="ab-panel"><h3>A—B 自选片段</h3><div class="ab-grid"><div><label class="field" for="shadow-a">A点（秒）</label><input type="number" id="shadow-a" min="0" step="0.1" value="0"><button class="text-btn" data-shadow="set-a">设为当前位置</button></div><div><label class="field" for="shadow-b">B点（秒）</label><input type="number" id="shadow-b" min="0" step="0.1" value="${timing.duration}"><button class="text-btn" data-shadow="set-b">设为当前位置</button></div><button class="btn secondary small" data-shadow="ab">播放 A—B</button></div></div><details id="shadow-transcript" class="shadow-transcript" open><summary>逐句原稿与练习重点</summary><p class="source-note" id="sentence-help">点击一句只播放这一句。先听一次，再跟读；数字和时间需要读准确。</p><div id="sentence-list">${t.segments.map((seg,i)=>`<button class="sentence-button" data-shadow-sentence="${i}"><span class="sentence-index">${String(i+1).padStart(2,'0')}</span><span><span class="sentence-english">${esc(seg[0])}</span><span class="sentence-hint">${esc(seg[1])} · ${audioTime(timing.segments[i].start)}—${audioTime(timing.segments[i].end)}</span></span><span class="sentence-play">▷</span></button>`).join('')}</div></details><div class="note" id="synthetic-note">本课录音由原创脚本生成，为Microsoft Zira合成语音，不是British Council原音，也不是实际求职经历。合成示范适合模仿表达，真实语速与口音练习请配合官方材料。</div></section><section class="panel" style="margin-top:20px"><span class="eyebrow">YOUR OWN AUDIO</span><h2>把已下载的音频带进来</h2><p class="sub">导入MP3、WAV、M4A或OGG后，可以调速和设置A—B循环。文件仅保存在这台设备的浏览器中，不上传GitHub。</p><input type="file" id="shadow-file" accept="audio/*,.mp3,.wav,.m4a,.ogg,.webm" hidden><div class="btn-row"><button class="btn secondary small" data-shadow="import">选择本地音频</button><button class="btn light small" data-shadow="use-local">使用本机保存的音频</button><button class="btn light small" data-shadow="use-original">恢复本课示范</button></div><p id="local-audio-label" class="source-note">本地文件不包含在学习记录JSON中，请另行保留原文件。</p><div class="btn-row"><a class="article-link inline-link" href="${t.official}" target="_blank" rel="noopener noreferrer">打开官方完整课程 / 查看原文 ↗</a></div><p class="source-note">官方材料保留原始课程上下文。第三方音频按其个人使用条款学习，本站不转载其音频或原稿。</p></section><section class="panel" style="margin-top:20px"><h3>每次只用10分钟</h3><ol class="step-list"><li>先听整段，不看原稿，记住主旨。</li><li>挑2—3句，每句听一次、跟读两次；从0.75×逐步回到1×。</li><li>把一句里的角色、数字或日期换掉，自己说一次。</li><li>到练习工作台录自己的版本，回听关键数字与停顿。</li></ol><div class="btn-row"><a class="btn small" href="#practice/${t.id}?kind=speaking">录自己的版本 ↗</a><a class="btn secondary small" href="#lesson/${t.id}">返回本周课程</a></div></section></div><aside class="panel audio-track-panel"><span class="eyebrow">12 WEEKS / 12 RECORDINGS</span><h3>选择本周音频</h3><div class="audio-track-list">${AUDIO_LESSONS.map(x=>`<a class="audio-track ${x.id===t.id?'selected':''}" href="#audio/${x.id}"><span>${String(x.id).padStart(2,'0')}</span><div>${esc(x.title)}<small>${audioTime(AUDIO_TIMINGS[x.id].duration)} · 原创合成语音</small></div></a>`).join('')}</div><div class="note">这些是练习示范。初测及阶段测评仍使用测试中心指定的陌生官方材料，不用已背熟的示范代替。</div></aside></div>`;
const audio=$('#shadow-audio');audio.playbackRate=rate;const s={id:t.id,audio,range:null,resume:null,pending:false,localURL:null,local:false,abort:new AbortController()};shadowSession=s;
function status(msg){const el=$('#shadow-status');if(el&&shadowSession===s)el.textContent=msg;}
function cancelGap(){clearTimeout(s.resume);s.resume=null;s.pending=false;}
async function play(){try{await audio.play();}catch{status('暂时无法播放，请稍后重试或下载后播放。');}}
function rangePlay(start,end,label){if(!Number.isFinite(audio.duration)){status('音频尚未加载完成，请稍后再试。');return;}if(start<0||end>audio.duration+.1||end-start<.25){status('请选择有效的A、B点，B点需比A点至少晚0.25秒。');return;}cancelGap();s.range={start,end,label};audio.currentTime=start;status(`播放${label} · ${audioTime(start)}—${audioTime(end)}`);play();}
function clearSentenceMarks(){document.querySelectorAll('[data-shadow-sentence]').forEach(b=>b.classList.remove('playing'));}
audio.addEventListener('timeupdate',()=>{if(shadowSession!==s)return;if(!s.local)document.querySelectorAll('[data-shadow-sentence]').forEach((b,i)=>b.classList.toggle('playing',audio.currentTime>=timing.segments[i].start&&audio.currentTime<timing.segments[i].end));const r=s.range;if(r&&audio.currentTime>=r.end-.025&&!s.pending){s.pending=true;audio.pause();if($('#shadow-loop').checked){const delay=Number($('#shadow-gap').value);status(delay?`留出${delay}秒，请跟读；随后重复${r.label}。`:`正在循环${r.label}。`);s.resume=setTimeout(()=>{if(shadowSession!==s)return;s.pending=false;audio.currentTime=r.start;play();},delay*1000);}else{status(`${r.label}已播放完，请模仿一次，或勾选循环后再次点击。`);s.range=null;s.pending=false;}}});
audio.addEventListener('pause',()=>{if(!s.pending){clearTimeout(s.resume);s.resume=null;}});
function updateAudioMetadata(){if(shadowSession!==s)return;audio.playbackRate=Number($('#shadow-rate').value);if(Number.isFinite(audio.duration)&&!s.range)$('#shadow-b').value=audio.duration.toFixed(2);}
audio.addEventListener('loadedmetadata',updateAudioMetadata);audio.addEventListener('durationchange',updateAudioMetadata);
audio.addEventListener('error',()=>status('音频加载失败。请刷新页面，或下载文件后导入本机播放器。'));
$('#shadow-rate').addEventListener('change',()=>{audio.playbackRate=Number($('#shadow-rate').value);persistPrefs();});$('#shadow-gap').addEventListener('change',persistPrefs);
$('#shadow-loop').addEventListener('change',()=>{if(!$('#shadow-loop').checked&&s.pending){cancelGap();status('循环已关闭，点击句子或播放按钮继续。');}});
function persistPrefs(){state.shadowPrefs||={};state.shadowPrefs[t.id]={rate:Number($('#shadow-rate').value),gap:Number($('#shadow-gap').value),local:s.local};save();}
async function attachLocal(rec,persist=true){if(shadowSession!==s)return;cancelGap();s.range=null;audio.pause();if(s.localURL)URL.revokeObjectURL(s.localURL);s.localURL=URL.createObjectURL(rec.blob);s.local=true;audio.src=s.localURL;audio.load();$('#audio-source-tag').textContent='本机音频';$('#shadow-download').href=s.localURL;$('#shadow-download').download=rec.name;$('#local-audio-label').textContent=`当前本机文件：${rec.name}。保存在此浏览器，不上传。`;$('#synthetic-note').hidden=true;$('#shadow-transcript').open=false;$('#sentence-help').textContent='当前是本地音频，没有自动对齐的逐句字幕；请用A—B选段，并参照对应的原文资料。';document.querySelectorAll('[data-shadow-sentence]').forEach(b=>b.disabled=true);clearSentenceMarks();status('本机音频已加载。设置A、B点后可循环跟读。');if(persist)persistPrefs();}
$('#shadow-file').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;if(f.size>80*1024*1024){toast('请选择80MB以内的音频文件。');return;}if(!(f.type.startsWith('audio/')||/\.(mp3|wav|m4a|ogg|webm)$/i.test(f.name))){toast('请选择支持的音频格式。');return;}const rec={id:t.id,blob:f,name:f.name};try{await personalAudio(t.id,rec);await attachLocal(rec);}catch{await attachLocal(rec);$('#local-audio-label').textContent=`当前文件：${f.name}。浏览器存储不可用，仅本次页面可用，请保留原文件。`;}});
$('#main').addEventListener('click',async e=>{if(shadowSession!==s)return;const sentence=e.target.closest('[data-shadow-sentence]');if(sentence&&!s.local){const i=Number(sentence.dataset.shadowSentence),seg=timing.segments[i];rangePlay(seg.start,seg.end,`第${i+1}句`);return;}const b=e.target.closest('[data-shadow]');if(!b)return;switch(b.dataset.shadow){case'whole':cancelGap();s.range=null;$('#shadow-loop').checked=false;audio.currentTime=0;status('整段播放。先抓住主旨，再挑句跟读。');play();break;case'pause':cancelGap();s.range=null;audio.pause();clearSentenceMarks();status('已暂停。');break;case'rewind':cancelGap();audio.currentTime=Math.max(s.range?.start||0,audio.currentTime-5);break;case'set-a':$('#shadow-a').value=audio.currentTime.toFixed(2);break;case'set-b':$('#shadow-b').value=audio.currentTime.toFixed(2);break;case'ab':rangePlay(Number($('#shadow-a').value),Number($('#shadow-b').value),'A—B片段');break;case'import':$('#shadow-file').click();break;case'use-local':try{const rec=await personalAudio(t.id);if(rec?.blob)attachLocal(rec);else toast('本周尚未保存本机音频，请先选择文件。');}catch{toast('本机存储不可用，请重新选择音频文件。');}break;case'use-original':state.shadowPrefs||={};state.shadowPrefs[t.id]={...state.shadowPrefs[t.id],local:false};save();cleanupListening();renderListening(t.id);break;}},{signal:s.abort.signal});
if(prefs.local)personalAudio(t.id).then(rec=>{if(rec?.blob)attachLocal(rec,false);}).catch(()=>{});
};
document.addEventListener('play',e=>{if(e.target.tagName==='AUDIO')document.querySelectorAll('audio').forEach(a=>{if(a!==e.target)a.pause();});},true);
